import type { TwinEventMap, TwinEventName, TwinEventListener } from "../types.js";
import { ErrorCode } from "../types.js";
import { TwinError } from "./errors.js";

const MAX_LISTENERS_PER_EVENT = 200;

/** 高频事件默认节流间隔（ms），可在构造时覆盖（设计文档 §6） */
const DEFAULT_THROTTLE: Partial<Record<TwinEventName, number>> = {
  SceneHover: 100,
  EntityHover: 100,
  CameraChanged: 50,
  SceneLoadingProgress: 100,
};

/** 类型化事件总线：交互回调不占用命令通道；高频事件按配置节流 */
export class TwinEventBus {
  private readonly listeners = new Map<string, Set<(payload: unknown) => void>>();
  private readonly lastEmit = new Map<string, { at: number; payload: unknown }>();
  private readonly timers = new Map<string, ReturnType<typeof setTimeout>>();

  constructor(
    private readonly throttle: Partial<Record<TwinEventName, number>> = DEFAULT_THROTTLE
  ) {}

  on<E extends TwinEventName>(event: E, listener: TwinEventListener<E>): () => void {
    let set = this.listeners.get(event);
    if (!set) {
      set = new Set();
      this.listeners.set(event, set);
    }
    if (set.size >= MAX_LISTENERS_PER_EVENT) {
      throw new TwinError(
        ErrorCode.LISTENER_LIMIT_EXCEEDED,
        `事件 ${event} 监听器已达上限 ${MAX_LISTENERS_PER_EVENT}`
      );
    }
    const wrapped = listener as (payload: unknown) => void;
    set.add(wrapped);
    return () => set!.delete(wrapped);
  }

  once<E extends TwinEventName>(event: E, listener: TwinEventListener<E>): () => void {
    const off = this.on(event, ((payload: TwinEventMap[E]) => {
      off();
      listener(payload);
    }) as TwinEventListener<E>);
    return off;
  }

  off<E extends TwinEventName>(event: E, listener: TwinEventListener<E>): void {
    this.listeners.get(event)?.delete(listener as (payload: unknown) => void);
  }

  emit<E extends TwinEventName>(event: E, payload: TwinEventMap[E]): void {
    const interval = this.throttle[event] ?? 0;
    if (interval > 0) {
      const now = Date.now();
      const last = this.lastEmit.get(event);
      if (last && now - last.at < interval) {
        this.scheduleTrailing(event, payload, interval);
        return;
      }
      this.lastEmit.set(event, { at: now, payload });
    }
    this.dispatch(event, payload);
  }

  private scheduleTrailing<E extends TwinEventName>(event: E, payload: TwinEventMap[E], interval: number): void {
    const last = this.lastEmit.get(event);
    if (last) last.payload = payload;
    if (this.timers.has(event)) return;
    const timer = setTimeout(() => {
      this.timers.delete(event);
      const l = this.lastEmit.get(event);
      if (l) {
        this.lastEmit.set(event, { at: Date.now(), payload: l.payload });
        this.dispatch(event, l.payload as TwinEventMap[E]);
      }
    }, interval);
    this.timers.set(event, timer);
  }

  private dispatch<E extends TwinEventName>(event: E, payload: TwinEventMap[E]): void {
    const set = this.listeners.get(event);
    if (!set) return;
    for (const fn of [...set]) {
      try {
        (fn as (p: TwinEventMap[E]) => void)(payload);
      } catch (err) {
        // 单个监听器异常不影响其他监听器，也不占用命令通道
        console.error(`[DigitalTwin] 事件 ${event} 监听器异常:`, err);
      }
    }
  }

  clear(): void {
    for (const timer of this.timers.values()) clearTimeout(timer);
    this.timers.clear();
    this.listeners.clear();
    this.lastEmit.clear();
  }
}
