import type { CommandDefinition, CommandMeta } from "../types.js";
import { ErrorCode } from "../types.js";
import { TwinError } from "./errors.js";

const COMMAND_NAME_RE = /^[A-Z][A-Za-z0-9]*(\.[A-Z][A-Za-z0-9]*)*$/;

/**
 * L2 命令注册表：内置命令与扩展命令共用同一注册表。
 * 内置命令（protected）不可被覆盖；自定义命令建议带业务前缀（如 'Biz.PatrolMode'）。
 */
export class CommandRegistry {
  private readonly commands = new Map<string, CommandDefinition>();

  register(def: CommandDefinition, opts: { internal?: boolean } = {}): void {
    if (!COMMAND_NAME_RE.test(def.name)) {
      throw new TwinError(
        ErrorCode.INVALID_PARAMS,
        `命令名 ${def.name} 不合法：需 PascalCase，自定义命令须带业务前缀（如 Biz.PatrolMode）`
      );
    }
    const existing = this.commands.get(def.name);
    if (existing?.protected || (existing && opts.internal && !def.protected)) {
      throw new TwinError(ErrorCode.COMMAND_REJECTED, `内置命令 ${def.name} 不可覆盖`);
    }
    if (existing && !existing.protected && opts.internal) {
      throw new TwinError(ErrorCode.COMMAND_REJECTED, `命令 ${def.name} 已被自定义注册占用`);
    }
    this.commands.set(def.name, { ...def, protected: def.protected ?? opts.internal });
  }

  unregister(command: string): void {
    const def = this.commands.get(command);
    if (!def) return;
    if (def.protected) {
      throw new TwinError(ErrorCode.COMMAND_REJECTED, `内置命令 ${command} 不可注销`);
    }
    this.commands.delete(command);
  }

  get(command: string): CommandDefinition | undefined {
    return this.commands.get(command);
  }

  list(): CommandMeta[] {
    return [...this.commands.values()].map((d) => ({
      name: d.name,
      category: d.category,
      since: d.since,
      deprecated: Boolean(d.deprecated),
      queue: d.queue ?? "parallel",
      internal: Boolean(d.protected),
    }));
  }

  /** 元数据导出：驱动文档站点与 IDE 提示同源（设计文档 §8） */
  exportMeta(): string {
    return JSON.stringify(this.list(), null, 2);
  }
}
