import type { CommandDefinition } from "../types.js";
import { ErrorCode } from "../types.js";
import { TwinError } from "./errors.js";

type Task = (signal: AbortSignal) => Promise<unknown>;

/**
 * 命令排队策略（设计文档 §4.3）：
 * - parallel: 立即执行（默认，查询类）
 * - serial:   全局 FIFO 串行链（场景切换等顺序敏感命令）
 * - latest:   同名命令取最新，未完成的旧命令被 abort（连续 CameraFlyTo 防动画堆叠）
 */
export class CommandQueue {
  private serialChain: Promise<unknown> = Promise.resolve();
  private readonly pendingLatest = new Map<string, AbortController>();
  private length = 0;

  constructor(private readonly maxQueue = 500) {}

  get currentLength(): number {
    return this.length;
  }

  async run(def: CommandDefinition, task: Task): Promise<unknown> {
    if (this.length >= this.maxQueue) {
      throw new TwinError(ErrorCode.QUEUE_OVERFLOW, `命令队列已达上限 ${this.maxQueue}，拒绝入队`);
    }
    this.length += 1;
    try {
      switch (def.queue ?? "parallel") {
        case "serial":
          return await this.runSerial(task);
        case "latest":
          return await this.runLatest(def.name, task);
        default:
          return await task(new AbortController().signal);
      }
    } finally {
      this.length -= 1;
    }
  }

  private runSerial(task: Task): Promise<unknown> {
    const next = this.serialChain.then(
      () => task(new AbortController().signal),
      () => task(new AbortController().signal) // 前序失败不阻断后续（失败隔离）
    );
    this.serialChain = next.catch(() => undefined);
    return next;
  }

  private runLatest(name: string, task: Task): Promise<unknown> {
    this.pendingLatest.get(name)?.abort();
    const controller = new AbortController();
    this.pendingLatest.set(name, controller);
    return task(controller.signal).finally(() => {
      if (this.pendingLatest.get(name) === controller) this.pendingLatest.delete(name);
    });
  }

  abortAll(): void {
    for (const controller of this.pendingLatest.values()) controller.abort();
    this.pendingLatest.clear();
  }
}
