import { ErrorCode } from "../types.js";

/** SDK 内部统一错误类型：携带错误码与可选详情，调度层捕获后规范化进响应信封 */
export class TwinError extends Error {
  readonly code: ErrorCode;
  readonly details?: unknown;

  constructor(code: ErrorCode, message: string, details?: unknown) {
    super(`[${code}] ${message}`);
    this.name = "TwinError";
    this.code = code;
    this.details = details;
  }
}

/** 未知异常 → 统一 1001 */
export function toTwinError(err: unknown): TwinError {
  if (err instanceof TwinError) return err;
  if (err instanceof Error) return new TwinError(ErrorCode.UNKNOWN_ERROR, err.message);
  return new TwinError(ErrorCode.UNKNOWN_ERROR, String(err));
}

export function errCommandNotFound(command: string): TwinError {
  return new TwinError(ErrorCode.COMMAND_NOT_FOUND, `命令未注册: ${command}`);
}

export function errDestroyed(): TwinError {
  return new TwinError(ErrorCode.ENGINE_DESTROYED, "实例已销毁，请重新 createDigitalTwin()");
}
