import type {
  CommandContext,
  CommandDefinition,
  DigitalTwinApi,
  DigitalTwinOptions,
  EngineFacade,
  TwinEventEmitter,
  TwinEventName,
  TwinEventListener,
  TwinLogger,
} from "./types.js";
import { ErrorCode } from "./types.js";
import { CommandRegistry } from "./core/registry.js";
import { CommandQueue } from "./core/queue.js";
import { TwinEventBus } from "./core/event-bus.js";
import { Scheduler } from "./core/scheduler.js";
import { createBuiltinCommands } from "./core/builtins.js";
import { createStubEngine } from "./core/engine-stub.js";
import { toTwinError } from "./core/errors.js";

const SDK_VERSION = "0.1.0";

/**
 * M2 入口：Babylon 适配层通过本注入点提供真实 EngineFacade。
 * engine 可为实例，或接收事件发射器的工厂（推荐：适配层借此把拾取/相机事件推入事件总线）。
 */
export interface InternalBootstrap {
  engine?: EngineFacade | ((emitter: TwinEventEmitter) => EngineFacade);
}

const LEVEL_ORDER = { debug: 10, info: 20, warn: 30, error: 40, silent: 99 } as const;

function createLogger(level: DigitalTwinOptions["logLevel"]): TwinLogger {
  const threshold = LEVEL_ORDER[level ?? "warn"];
  const method: Record<keyof typeof LEVEL_ORDER, "log" | "info" | "warn" | "error" | null> = {
    debug: "log",
    info: "info",
    warn: "warn",
    error: "error",
    silent: null,
  };
  const log = (lv: keyof typeof LEVEL_ORDER, msg: string, meta?: object) => {
    const fn = method[lv];
    if (fn && LEVEL_ORDER[lv] >= threshold) console[fn]("[DigitalTwin]", msg, meta ?? "");
  };
  return {
    debug: (m, meta) => log("debug", m, meta),
    info: (m, meta) => log("info", m, meta),
    warn: (m, meta) => log("warn", m, meta),
    error: (m, meta) => log("error", m, meta),
  };
}

/** 单实例守卫（决策：单实例设计） */
let activeInstance: DigitalTwinApi | null = null;

export async function createDigitalTwin(
  options: DigitalTwinOptions,
  internal: InternalBootstrap = {}
): Promise<DigitalTwinApi> {
  if (activeInstance) {
    console.warn("[DigitalTwin] 检测到重复创建实例：将先销毁已有实例（单实例设计）");
    await activeInstance.destroy();
  }

  const logger = createLogger(options.logLevel);
  const events = new TwinEventBus();
  const engine =
    typeof internal.engine === "function"
      ? internal.engine(events)
      : (internal.engine ?? createStubEngine());
  const registry = new CommandRegistry();
  const queue = new CommandQueue();

  for (const def of createBuiltinCommands(engine, options.scenes)) {
    registry.register(def, { internal: true });
  }

  let destroyed = false;
  let sceneReady = false;

  const scheduler = new Scheduler(registry, queue, {
    logger,
    defaultTimeout: options.defaultTimeout ?? 10_000,
    isReady: () => engine.isReady(),
    // LoadScene/SwitchScene 是使引擎就绪的命令本身，执行前不要求就绪
    requiresEngine: (def) => def.category !== "custom" && def.name !== "LoadScene" && def.name !== "SwitchScene",
    context: { engine, logger } satisfies Omit<CommandContext, "signal" | "requestId">,
  });

  const api: DigitalTwinApi = {
    execute: (async (command: string, ...args: unknown[]) => {
      const params = args[0];
      if (destroyed) {
        return {
          code: ErrorCode.ENGINE_DESTROYED,
          message: "[1006] 实例已销毁，请重新 createDigitalTwin()",
          command,
          requestId: "n/a",
          elapsed: 0,
        };
      }
      return scheduler.execute(command, params);
    }) as DigitalTwinApi["execute"],

    on(event, listener) {
      return events.on(event, listener);
    },

    once(event, listener) {
      return events.once(event, listener);
    },

    off(event, listener) {
      events.off(event, listener);
    },

    registerCommand(definition) {
      if (destroyed) throw toTwinError(new Error("实例已销毁"));
      registry.register({ ...definition, protected: false });
    },

    unregisterCommand(command) {
      registry.unregister(command);
    },

    listCommands() {
      return registry.list();
    },

    async destroy() {
      if (destroyed) return;
      destroyed = true;
      scheduler.markDestroyed();
      events.emit("RuntimeWarning", { code: 1006, message: "实例销毁" });
      events.clear();
      await engine.dispose();
      if (activeInstance === api) activeInstance = null;
    },

    get diagnostics() {
      return {
        version: SDK_VERSION,
        backend: "webgl2" as const,
        fps: 0,
        queueLength: queue.currentLength,
        sceneReady,
        coverings: {},
      };
    },
  };

  activeInstance = api;
  sceneReady = engine.isReady();
  return api;
}

export type { TwinEventName, TwinEventListener, CommandDefinition };
