import type { ApiResponse } from "../types.js";
import { ErrorCode } from "../types.js";
import { TwinError, toTwinError } from "./errors.js";

let seq = 0;
const rand = (): string => {
  try {
    return crypto.randomUUID();
  } catch {
    seq += 1;
    return `req-${Date.now().toString(36)}-${seq}`;
  }
};

export interface EnvelopeContext {
  command: string;
  requestId?: string;
  startedAt?: number;
}

export function ok<T>(ctx: EnvelopeContext, data: T): ApiResponse<T> {
  return {
    code: ErrorCode.OK,
    message: "ok",
    data,
    command: ctx.command,
    requestId: ctx.requestId ?? rand(),
    elapsed: Date.now() - (ctx.startedAt ?? Date.now()),
  };
}

export function fail(ctx: EnvelopeContext, err: unknown): ApiResponse<never> {
  const twinErr = toTwinError(err);
  return {
    code: twinErr.code,
    message: twinErr.message,
    command: ctx.command,
    requestId: ctx.requestId ?? rand(),
    elapsed: Date.now() - (ctx.startedAt ?? Date.now()),
  };
}

/** 参数校验失败 → 2002，message 附带首个失败详情（设计文档 §4.2） */
export function invalidParams(
  command: string,
  errors: ReadonlyArray<{ path: string; rule: string; detail: string }>
): TwinError {
  const first = errors[0];
  const summary = first ? `${first.path} ${first.rule}: ${first.detail}` : "参数结构非法";
  return new TwinError(ErrorCode.INVALID_PARAMS, `${command} 参数校验失败 — ${summary}`, errors);
}
