import type {
  CameraRoamParams,
  CameraState,
  EngineFacade,
  EntityOutlineParams,
  EntityHighlightParams,
  EntitySelector,
  LayerInfo,
  LightEffectParams,
  LocateEntityParams,
  MoveEntityByPathParams,
  ParticleEffectParams,
  SceneInfo,
  SceneManifest,
  SetCameraLimitParams,
  SetEntityVisibleParams,
  SetHeatmapParams,
  HighlightRegionParams,
  SetLayerOpacityParams,
  SetLayerVisibleParams,
  SetWeatherEffectParams,
  SwitchSceneParams,
  UpdateHeatmapParams,
  UpdatePOIParams,
  AddPOIParams,
  AddPathParams,
  Add3DTextParams,
  Vector3Like,
} from "../types.js";
import { ErrorCode } from "../types.js";
import { TwinError } from "./errors.js";

/**
 * 引擎门面桩实现：M1 阶段验证框架链路（注册表/调度/信封/事件），
 * M2 由 digital-twin-core 的 BabylonEngineFacade 替换。
 * 除 loadScene（支持 programmatic: 场景标记就绪）外全部返回 ENGINE_NOT_READY。
 */
export function createStubEngine(): EngineFacade {
  const notReady = (op: string): never => {
    throw new TwinError(
      ErrorCode.ENGINE_NOT_READY,
      `桩引擎不支持 ${op}：请接入 @your-scope/digital-twin-core 提供的 BabylonEngineFacade`
    );
  };

  let ready = false;

  return {
    isReady: () => ready,
    loadScene: async () => {
      ready = true;
      return { sceneId: "stub", ready: true, entityCount: 0, layers: [] };
    },
    switchScene: async (_m: SceneManifest, _p: SwitchSceneParams): Promise<SceneInfo> =>
      notReady("switchScene"),
    getSceneInfo: (): SceneInfo => ({ sceneId: "stub", ready, entityCount: 0, layers: [] }),
    setEnvironment: async () => notReady("setEnvironment"),
    cameraFlyTo: async (): Promise<CameraState> => notReady("cameraFlyTo"),
    cameraFocusOn: async (): Promise<CameraState> => notReady("cameraFocusOn"),
    cameraRoamStart: async (_p: CameraRoamParams) => notReady("cameraRoamStart"),
    cameraRoamStop: async () => notReady("cameraRoamStop"),
    getCameraState: (): CameraState => notReady("getCameraState"),
    setCameraLimit: async (_p: SetCameraLimitParams) => notReady("setCameraLimit"),
    resetCameraView: async (): Promise<CameraState> => notReady("resetCameraView"),
    setEntityVisible: async (_p: SetEntityVisibleParams) => notReady("setEntityVisible"),
    setEntityOutline: async (_p: EntityOutlineParams) => notReady("setEntityOutline"),
    setEntityHighlight: async (_p: EntityHighlightParams) => notReady("setEntityHighlight"),
    locateEntity: async (_p: LocateEntityParams) => notReady("locateEntity"),
    getEntityInfo: (_s: EntitySelector) => notReady("getEntityInfo"),
    moveEntityByPath: async (_p: MoveEntityByPathParams) => notReady("moveEntityByPath"),
    getLayerList: (): LayerInfo[] => [],
    setLayerVisible: async (_p: SetLayerVisibleParams) => notReady("setLayerVisible"),
    setLayerOpacity: async (_p: SetLayerOpacityParams) => notReady("setLayerOpacity"),
    setWeatherEffect: async (_p: SetWeatherEffectParams) => notReady("setWeatherEffect"),
    setHeatmap: async (_p: SetHeatmapParams) => notReady("setHeatmap"),
    updateHeatmap: async (_p: UpdateHeatmapParams) => notReady("updateHeatmap"),
    removeHeatmap: async () => notReady("removeHeatmap"),
    setParticleEffect: async (_p: ParticleEffectParams) => notReady("setParticleEffect"),
    setLightEffect: async (_p: LightEffectParams) => notReady("setLightEffect"),
    setHighlightRegion: async (_p: HighlightRegionParams) => notReady("setHighlightRegion"),
    addPOI: async (_p: AddPOIParams) => notReady("addPOI"),
    updatePOI: async (_p: UpdatePOIParams) => notReady("updatePOI"),
    addPath: async (_p: AddPathParams) => notReady("addPath"),
    add3DText: async (_p: Add3DTextParams) => notReady("add3DText"),
    removeCovering: async () => notReady("removeCovering"),
    clearCoverings: async () => notReady("clearCoverings"),
    dispose: async () => {
      ready = false;
    },
  };
}

export type { Vector3Like };
