/**
 * DigitalTwin API - TypeScript 类型定义（v1.0 已批准定稿）
 *
 * 对外稳定的公共契约层。所有接口均为纯类型声明，不包含实现。
 * 命名风格对齐 51World SuperAPI（PascalCase 动词命令 + On 前缀事件回调）。
 * 内部引擎为 Babylon.js，但任何 Babylon 类型不得泄漏到本文件中。
 *
 * 已确认决策基线（2026-08-23）：
 * - D1 坐标系：仅引擎内部米制坐标，经纬度换算由业务方基于 SceneInfo.origin 完成
 * - D2 数据通道：SDK 不内置 WS/MQTT，业务层自行驱动 execute
 * - D3 POI 安全：content 渲染前经标签白名单过滤（禁 script/iframe）
 * - D4 场景切换：不保留热状态（相机/覆盖物随切换重置）
 * - D5 发布形态：私有 npm registry + ESM only
 * - D6 鉴权：仅预留 capability 扩展点，不实现
 */

/* ============================================================
 * 1. 基础类型与统一响应信封
 * ============================================================ */

/** 统一响应信封：所有 execute() 调用（无论成败）都以此结构 resolve */
export interface ApiResponse<T = void> {
  /** 错误码，0 表示成功；非 0 见 ErrorCode */
  code: number;
  /** 人类可读信息（成功时可返回 'ok' 或命令说明） */
  message: string;
  /** 命令返回数据；失败时为 undefined */
  data?: T;
  /** 回显命令名，便于日志排查 */
  command: string;
  /** 请求追踪 ID，与错误日志一一对应 */
  requestId: string;
  /** 命令耗时（ms，含排队时间） */
  elapsed: number;
}

/** 统一错误码规范（分段：1xxx 通用 / 2xxx 调度 / 3xxx 场景相机 / 4xxx 实体图层 / 5xxx 特效覆盖物 / 6xxx 事件） */
export enum ErrorCode {
  OK = 0,

  // ---- 1xxx 通用 / 运行时 ----
  UNKNOWN_ERROR = 1001,
  ENGINE_INIT_FAILED = 1002,
  WEBGL_UNSUPPORTED = 1003,
  CONTEXT_LOST = 1004,
  ASSET_LOAD_FAILED = 1005,
  ENGINE_DESTROYED = 1006,

  // ---- 2xxx 命令调度 / 协议 ----
  COMMAND_NOT_FOUND = 2001,
  INVALID_PARAMS = 2002,
  COMMAND_TIMEOUT = 2003,
  ENGINE_NOT_READY = 2004,
  COMMAND_REJECTED = 2005,
  QUEUE_OVERFLOW = 2006,

  // ---- 3xxx 场景 / 相机 ----
  SCENE_NOT_FOUND = 3001,
  SCENE_LOAD_FAILED = 3002,
  CAMERA_PARAM_OUT_OF_RANGE = 3003,
  ROAM_PATH_INVALID = 3004,

  // ---- 4xxx 实体 / 图层 ----
  ENTITY_NOT_FOUND = 4001,
  LAYER_NOT_FOUND = 4002,
  LAYER_OPERATION_FAILED = 4003,
  ENTITY_OPERATION_FAILED = 4004,

  // ---- 5xxx 特效 / 覆盖物 ----
  EFFECT_NOT_SUPPORTED = 5001,
  COVERING_NOT_FOUND = 5002,
  HEATMAP_DATA_INVALID = 5003,
  RESOURCE_LIMIT_EXCEEDED = 5004,

  // ---- 6xxx 事件 / 交互 ----
  UNKNOWN_EVENT = 6001,
  LISTENER_LIMIT_EXCEEDED = 6002,
}

/** 参数校验错误详情（INVALID_PARAMS 时随 data 或 message 返回） */
export interface ValidationError {
  /** JSON Pointer 路径，如 "/position/y" */
  path: string;
  /** 违反的规则，如 'required' | 'type' | 'min' | 'max' | 'enum' */
  rule: string;
  /** 期望与实际值的简述 */
  detail: string;
}

/** 三维坐标（场景坐标系，米） */
export interface Vector3Like {
  x: number;
  y: number;
  z: number;
}

/** 相机姿态：位置 + 欧拉角（度） */
export interface CameraPose {
  position: Vector3Like;
  /** 俯仰角，-90(正下) ~ 0(水平) ~ 90(正上) */
  pitch: number;
  /** 偏航角，0 ~ 360 */
  yaw: number;
}

/** 实体定位器：三种寻址方式任选其一 */
export type EntitySelector =
  | { eids: string[] }
  | { entityNames: string[] }
  | { customIds: string[] };

/** 目标定位：实体或坐标 */
export type FocusTarget =
  | { entity: EntitySelector }
  | { position: Vector3Like };

/* ============================================================
 * 2. 初始化与实例生命周期
 * ============================================================ */

export interface DigitalTwinOptions {
  /** 挂载容器 DOM 元素或其 id */
  container: string | HTMLElement;
  /** 场景清单（场景 id -> 场景描述地址），供 LoadScene/SwitchScene 使用 */
  scenes: Record<string, SceneManifest>;
  /** 引擎选项（对内映射到 Babylon.js Engine 创建参数） */
  engine?: EngineOptions;
  /** 全局命令超时（ms），默认 10000 */
  defaultTimeout?: number;
  /** 日志级别，默认 'warn' */
  logLevel?: 'debug' | 'info' | 'warn' | 'error' | 'silent';
  /** 是否在控制台打印命令耗时（性能排查用），默认 false */
  commandProfiling?: boolean;
}

export interface EngineOptions {
  /** 渲染后端偏好，默认 'webgl2'（探测失败自动回退） */
  backend?: 'webgl2' | 'webgpu';
  /** 像素密度上限，默认 min(devicePixelRatio, 2) */
  maxPixelRatio?: number;
  /** 抗锯齿，默认 true */
  antialias?: boolean;
  /** 自适应渲染（静止时降帧省电），默认 true */
  adaptiveRate?: boolean;
}

export interface SceneManifest {
  /** 场景资源地址（.babylon / glTF / glb） */
  url: string;
  /** 资源版本或哈希，用于缓存失效 */
  version?: string;
  /** 预加载策略，默认 'lazy' */
  preload?: 'lazy' | 'eager';
}

/* ============================================================
 * 3. 命令参数与返回值定义（按功能域分组）
 * ============================================================ */

/* ---------- 3.1 场景 ---------- */

export interface LoadSceneParams {
  sceneId: string;
  /** 相机初始姿态，缺省用场景内置视角 */
  initialCamera?: CameraPose;
  /** 是否显示加载进度事件 SceneLoadingProgress */
  reportProgress?: boolean;
}

export interface SwitchSceneParams extends LoadSceneParams {
  /** 过渡动画，默认 'fade'（500ms） */
  transition?: 'none' | 'fade';
}

export interface SceneInfo {
  sceneId: string;
  /** 当前场景是否就绪（资源加载并完成首帧渲染） */
  ready: boolean;
  /** 场景内实体总数 */
  entityCount: number;
  /** 图层列表 */
  layers: LayerInfo[];
  /** 场景坐标系原点的经纬度（如有 GIS 配准） */
  origin?: { lng: number; lat: number };
}

export interface SetEnvironmentParams {
  /** 时间：0-24 小时，驱动太阳高度角与光照色温 */
  timeOfDay?: number;
  /** 天气：与 SetWeatherEffect 特效联动的基础大气状态 */
  weather?: 'clear' | 'cloudy' | 'overcast';
}

/* ---------- 3.2 相机 ---------- */

export interface CameraFlyToParams {
  /** 目标姿态 */
  pose: CameraPose;
  /** 飞行时长（ms），0 表示瞬移，默认 1500 */
  duration?: number;
  /** 缓动曲线，默认 'easeInOutCubic' */
  easing?:
    | 'linear'
    | 'easeInOutCubic'
    | 'easeOutQuart'
    | 'easeInOutQuad';
}

export interface CameraFocusOnParams {
  /** 聚焦目标：实体或坐标 */
  target: FocusTarget;
  /** 观察距离（米），默认取目标包围盒对角线的 2 倍 */
  distance?: number;
  /** 俯仰/偏航覆盖；缺省保持当前姿态方向 */
  pitch?: number;
  yaw?: number;
  duration?: number;
}

export interface CameraRoamParams {
  /** 漫游路径点（首尾自动闭合可选） */
  keyframes: Array<CameraPose & { duration?: number }>;
  /** 循环模式，默认 'once' */
  loop?: 'once' | 'loop' | 'pingpong';
  /** 全程时长（ms），设置后各段按比例分配 */
  totalDuration?: number;
}

export interface CameraState extends CameraPose {
  /** 当前相机模式 */
  mode: 'free' | 'orbit' | 'roaming';
  /** 视场角（度） */
  fov: number;
}

export interface SetCameraLimitParams {
  /** 位置边界盒（场景坐标） */
  positionBox?: { min: Vector3Like; max: Vector3Like };
  /** 俯仰角限制（度） */
  pitchRange?: { min: number; max: number };
  /** 偏航角限制（度），不设为无限 */
  yawRange?: { min: number; max: number };
  /** 缩放距离限制（米） */
  distanceRange?: { min: number; max: number };
}

/* ---------- 3.3 实体 / 模型 ---------- */

export interface SetEntityVisibleParams {
  targets: EntitySelector;
  visible: boolean;
}

export interface EntityOutlineParams {
  targets: EntitySelector;
  enable: boolean;
  /** 描边颜色，默认 '#FF6A00' */
  color?: string;
  /** 线宽（px），默认 2 */
  thickness?: number;
}

export interface EntityHighlightParams {
  targets: EntitySelector;
  enable: boolean;
  /** 高亮颜色，默认 '#409EFF'，透明度 0.4 */
  color?: string;
  opacity?: number;
}

export interface LocateEntityParams {
  targets: EntitySelector;
  /** 定位后相机观察距离（米） */
  distance?: number;
  /** 是否临时高亮定位结果，默认 true，3 秒后自动消除 */
  flashHighlight?: boolean;
}

export interface EntityInfo {
  eid: string;
  entityName?: string;
  customId?: string;
  /** 实体类型（对齐 WDP 实体类型表的字符串枚举） */
  entityType: string;
  visible: boolean;
  /** 世界坐标包围盒 */
  boundingBox: { min: Vector3Like; max: Vector3Like };
  layerName?: string;
  /** 业务自定义属性（场景资产内挂载的 metadata） */
  properties?: Record<string, unknown>;
}

export interface MoveEntityByPathParams {
  targets: EntitySelector;
  /** 路径点序列 */
  path: Vector3Like[];
  /** 是否沿路径朝向运动方向，默认 true */
  orientToPath?: boolean;
  /** 总时长（ms） */
  duration: number;
  loop?: 'once' | 'loop' | 'pingpong';
}

/* ---------- 3.4 图层 ---------- */

export interface LayerInfo {
  layerName: string;
  visible: boolean;
  /** 图层内实体数量 */
  entityCount: number;
  /** 用户可读名称 */
  label?: string;
}

export interface SetLayerVisibleParams {
  layerNames: string[];
  visible: boolean;
}

export interface SetLayerOpacityParams {
  layerName: string;
  /** 0-1，1 为不透明 */
  opacity: number;
}

/* ---------- 3.5 特效 ---------- */

export type WeatherType = 'rain' | 'snow' | 'fog' | 'clear';

export interface SetWeatherEffectParams {
  type: WeatherType;
  /** 强度 0-1，默认 0.5 */
  intensity?: number;
}

export interface HeatmapPoint {
  position: Vector3Like;
  /** 权重 0-1 */
  weight: number;
}

export interface SetHeatmapParams {
  /** 热力图实例名，用于后续更新/移除 */
  heatmapId: string;
  points: HeatmapPoint[];
  /** 影响半径（米），默认 50 */
  radius?: number;
  /** 色带，默认 蓝->绿->黄->红 */
  gradient?: Array<{ color: string; stop: number }>;
  /** 渲染模式，默认 'plane'（贴地平面）；'column' 为柱状热力图 */
  mode?: 'plane' | 'column';
  /** 柱状模式高度（米），mode='column' 时生效 */
  columnHeight?: number;
}

export interface UpdateHeatmapParams {
  heatmapId: string;
  /** 增量或全量替换数据点 */
  points: HeatmapPoint[];
}

export interface ParticleEffectParams {
  effectId: string;
  /** 预置粒子类型（火焰/喷泉/烟雾等）或自定义资产地址 */
  preset?: 'fire' | 'smoke' | 'fountain' | 'explosion' | string;
  position: Vector3Like;
  scale?: number;
  /** 是否随载体实体移动（如车辆尾焰） */
  attachTo?: EntitySelector;
}

export interface LightEffectParams {
  lightId: string;
  type: 'point' | 'spot' | 'directional';
  position?: Vector3Like;
  direction?: Vector3Like;
  color?: string;
  intensity?: number;
  enable: boolean;
}

export interface HighlightRegionParams {
  regionId: string;
  /** 区域多边形顶点（场景坐标） */
  boundary: Vector3Like[];
  color?: string;
  opacity?: number;
  /** 是否抬升为立体高亮墙，默认 false */
  extruded?: boolean;
  /** 抬升高度（米） */
  extrudeHeight?: number;
}

/* ---------- 3.6 标注 / 覆盖物 ---------- */

export interface AddPOIParams {
  poiId: string;
  position: Vector3Like;
  /** DOM 标注内容（HTML 片段），由 API 层托管在覆盖层中；渲染前经标签白名单过滤（决策 D3） */
  content: string;
  /** 屏幕偏移（px） */
  offset?: { x: number; y: number };
  /** 显示策略，默认 'always' */
  display?: 'always' | 'hover' | 'click';
  /** 深度测试：true 时被遮挡隐藏，默认 false */
  occlusionTest?: boolean;
  /** 相机距离显隐阈值（米） */
  visibleDistance?: { min?: number; max?: number };
}

export interface AddPathParams {
  pathId: string;
  points: Vector3Like[];
  color?: string;
  width?: number;
  /** 是否贴地，默认 true */
  clampToGround?: boolean;
  /** 流动动画速度，0 为静态，默认 0 */
  flowSpeed?: number;
}

export interface Add3DTextParams {
  textId: string;
  position: Vector3Like;
  text: string;
  fontSize?: number;
  color?: string;
  /** 始终面向相机，默认 true */
  billboard?: boolean;
}

export interface RemoveCoveringParams {
  /** 覆盖物 id（POI/路径/热力图/粒子/灯光/高亮区域通用） */
  coveringIds: string[];
}

export type CoveringType = 'poi' | 'path' | 'heatmap' | 'particle' | 'light' | 'region' | 'text3d';

export interface ClearCoveringsParams {
  /** 按类型清空，缺省清空全部 */
  types?: CoveringType[];
}

export interface UpdatePOIParams {
  poiId: string;
  position?: Vector3Like;
  content?: string;
}

/* ============================================================
 * 4. 事件系统
 * ============================================================ */

/** 所有可订阅事件的事件映射表 */
export interface TwinEventMap {
  /** 场景就绪（LoadScene/SwitchScene 完成首帧渲染后触发一次） */
  SceneReady: { sceneId: string; loadElapsed: number };
  /** 场景加载进度 */
  SceneLoadingProgress: { sceneId: string; progress: number };
  /** 场景空白处点击 */
  SceneClick: { position: Vector3Like; screen: { x: number; y: number } };
  /** 场景空白处悬停（节流 100ms） */
  SceneHover: { position: Vector3Like | null };
  /** 实体点击 */
  EntityClick: { eid: string; entityName?: string; customId?: string; screen: { x: number; y: number } };
  /** 实体悬停（节流 100ms，null 表示离开） */
  EntityHover: { eid: string | null };
  /** 相机姿态变化（节流 50ms） */
  CameraChanged: { pose: CameraPose };
  /** 拾取坐标模式下的选点结果 */
  CoordPicked: { position: Vector3Like };
  /** 引擎上下文丢失（WebGL context lost） */
  ContextLost: { recoverable: boolean };
  /** 运行时告警（如资源降级、性能保护触发） */
  RuntimeWarning: { code: number; message: string };
}

/** 事件名联合类型 */
export type TwinEventName = keyof TwinEventMap;

/** 事件监听器 */
export type TwinEventListener<E extends TwinEventName> = (
  payload: TwinEventMap[E]
) => void;

/** 取消订阅函数 */
export type Unsubscribe = () => void;

/* ============================================================
 * 5. 统一入口：DigitalTwinApi
 * ============================================================ */

export interface DigitalTwinApi {
  /**
   * 唯一的命令执行入口。
   * - 命令未注册 / 参数非法 / 超时 / 引擎异常，均以 ApiResponse(code!=0) resolve（不 reject），
   *   只有 SDK 自身的编程错误（如实例已 destroy）才会 reject。
   * - params 类型由命令名映射（见 CommandParamsMap）推导。
   */
  execute<C extends keyof CommandParamsMap>(
    command: C,
    ...args: CommandParamsMap[C] extends void ? [] : [params: CommandParamsMap[C]]
  ): Promise<ApiResponse<CommandResultMap[C]>>;

  /** 事件订阅，返回取消订阅函数 */
  on<E extends TwinEventName>(event: E, listener: TwinEventListener<E>): Unsubscribe;

  /** 取消事件订阅（传入原引用） */
  off<E extends TwinEventName>(event: E, listener: TwinEventListener<E>): void;

  /** 单次订阅（触发一次后自动取消） */
  once<E extends TwinEventName>(event: E, listener: TwinEventListener<E>): Unsubscribe;

  /** 注册自定义命令（可扩展机制），命令名建议以业务前缀命名避免冲突，如 'Xxx.BizCommand' */
  registerCommand(definition: CommandDefinition): void;

  /** 注销命令（仅允许注销通过 registerCommand 注册的命令） */
  unregisterCommand(command: string): void;

  /** 查询已注册命令清单（含元信息，用于文档生成与调试） */
  listCommands(): CommandMeta[];

  /** 主动销毁实例，释放 WebGL 上下文与全部资源；之后所有 execute 返回 ENGINE_DESTROYED */
  destroy(): Promise<void>;

  /** 只读诊断信息 */
  readonly diagnostics: Diagnostics;
}

/** 命令名 -> 参数 映射（SDK 内置命令的完整清单） */
export interface CommandParamsMap {
  // 场景
  LoadScene: LoadSceneParams;
  SwitchScene: SwitchSceneParams;
  GetSceneInfo: void;
  SetEnvironment: SetEnvironmentParams;
  // 相机
  CameraFlyTo: CameraFlyToParams;
  CameraFocusOn: CameraFocusOnParams;
  CameraRoamStart: CameraRoamParams;
  CameraRoamStop: void;
  GetCameraInfo: void;
  SetCameraLimit: SetCameraLimitParams;
  ResetCameraView: void;
  // 实体
  SetEntityVisible: SetEntityVisibleParams;
  SetEntityOutline: EntityOutlineParams;
  SetEntityHighlight: EntityHighlightParams;
  LocateEntity: LocateEntityParams;
  GetEntityInfo: EntitySelector;
  MoveEntityByPath: MoveEntityByPathParams;
  // 图层
  GetLayerList: void;
  SetLayerVisible: SetLayerVisibleParams;
  SetLayerOpacity: SetLayerOpacityParams;
  // 特效
  SetWeatherEffect: SetWeatherEffectParams;
  SetHeatmap: SetHeatmapParams;
  UpdateHeatmap: UpdateHeatmapParams;
  RemoveHeatmap: { heatmapId: string };
  SetParticleEffect: ParticleEffectParams;
  SetLightEffect: LightEffectParams;
  SetHighlightRegion: HighlightRegionParams;
  // 标注 / 覆盖物
  AddPOI: AddPOIParams;
  UpdatePOI: UpdatePOIParams;
  AddPath: AddPathParams;
  Add3DText: Add3DTextParams;
  RemoveCovering: RemoveCoveringParams;
  ClearCoverings: ClearCoveringsParams;
}

/** 命令名 -> 返回值 映射 */
export interface CommandResultMap {
  LoadScene: SceneInfo;
  SwitchScene: SceneInfo;
  GetSceneInfo: SceneInfo;
  SetEnvironment: void;
  CameraFlyTo: CameraState;
  CameraFocusOn: CameraState;
  CameraRoamStart: { roamId: string };
  CameraRoamStop: void;
  GetCameraInfo: CameraState;
  SetCameraLimit: void;
  ResetCameraView: CameraState;
  SetEntityVisible: { affected: number };
  SetEntityOutline: { affected: number };
  SetEntityHighlight: { affected: number };
  LocateEntity: void;
  GetEntityInfo: EntityInfo[];
  MoveEntityByPath: { moveId: string };
  GetLayerList: LayerInfo[];
  SetLayerVisible: { affected: number };
  SetLayerOpacity: void;
  SetWeatherEffect: void;
  SetHeatmap: void;
  UpdateHeatmap: void;
  RemoveHeatmap: void;
  SetParticleEffect: void;
  SetLightEffect: void;
  SetHighlightRegion: void;
  AddPOI: void;
  UpdatePOI: void;
  AddPath: void;
  Add3DText: void;
  RemoveCovering: { removed: number };
  ClearCoverings: { removed: number };
}

/* ============================================================
 * 6. 命令注册机制（可扩展性）
 * ============================================================ */

/** 命令功能域（用于文档分组与权限隔离预留） */
export type CommandCategory =
  | 'scene'
  | 'camera'
  | 'entity'
  | 'layer'
  | 'effect'
  | 'covering'
  | 'custom';

/** 命令执行上下文：适配层与引擎交互的唯一通道（不暴露 Babylon 类型） */
export interface CommandContext {
  /** 读取引擎场景抽象（能力受限于本接口定义） */
  engine: EngineFacade;
  /** 结构化日志 */
  logger: TwinLogger;
  /** 取消信号：命令超时或实例销毁时触发，长任务应响应 */
  signal: AbortSignal;
  /** 发起本次调用的 requestId */
  requestId: string;
}

export interface CommandDefinition<P = any, R = any> {
  /** 命令名，PascalCase；自定义命令必须带业务前缀 */
  name: string;
  category: CommandCategory;
  /** 参数声明（JSON Schema 子集，用于运行时校验与文档生成） */
  params?: Record<string, ParamSchema>;
  /** 命令处理函数 */
  handler: (ctx: CommandContext, params: P) => Promise<R> | R;
  /** 超时（ms），缺省用实例 defaultTimeout */
  timeout?: number;
  /** 排队策略，默认 'parallel' */
  queue?: 'parallel' | 'serial' | 'latest';
  /** 引入版本，如 '1.0.0' */
  since?: string;
  /** 弃用标记（附替代命令） */
  deprecated?: { since: string; useInstead?: string };
  /** 是否写入 SDK 内置命令保护名单（内置命令不可被覆盖） */
  protected?: boolean;
}

export interface ParamSchema {
  type: 'number' | 'string' | 'boolean' | 'array' | 'object';
  required?: boolean;
  min?: number;
  max?: number;
  enum?: string[];
  items?: ParamSchema;
  properties?: Record<string, ParamSchema>;
  description?: string;
}

export interface CommandMeta {
  name: string;
  category: CommandCategory;
  since?: string;
  deprecated?: boolean;
  queue: 'parallel' | 'serial' | 'latest';
  internal: boolean;
}

/** 事件发射器：引擎适配层通过它把拾取/相机事件推入 SDK 事件总线 */
export interface TwinEventEmitter {
  emit<E extends TwinEventName>(event: E, payload: TwinEventMap[E]): void;
}

/** 引擎门面（L1 适配层契约，扩展开发者通过它操作引擎，而非直接触碰 Babylon） */
export interface EngineFacade {
  isReady(): boolean;
  // ---- 场景 ----
  loadScene(manifest: SceneManifest, params: LoadSceneParams): Promise<SceneInfo>;
  switchScene(manifest: SceneManifest, params: SwitchSceneParams): Promise<SceneInfo>;
  getSceneInfo(): SceneInfo;
  setEnvironment(params: SetEnvironmentParams): Promise<void>;
  // ---- 相机 ----
  cameraFlyTo(params: CameraFlyToParams): Promise<CameraState>;
  cameraFocusOn(params: CameraFocusOnParams): Promise<CameraState>;
  cameraRoamStart(params: CameraRoamParams): Promise<{ roamId: string }>;
  cameraRoamStop(): Promise<void>;
  getCameraState(): CameraState;
  setCameraLimit(params: SetCameraLimitParams): Promise<void>;
  resetCameraView(): Promise<CameraState>;
  // ---- 实体 ----
  setEntityVisible(params: SetEntityVisibleParams): Promise<{ affected: number }>;
  setEntityOutline(params: EntityOutlineParams): Promise<{ affected: number }>;
  setEntityHighlight(params: EntityHighlightParams): Promise<{ affected: number }>;
  locateEntity(params: LocateEntityParams): Promise<void>;
  getEntityInfo(selector: EntitySelector): EntityInfo[];
  moveEntityByPath(params: MoveEntityByPathParams): Promise<{ moveId: string }>;
  // ---- 图层 ----
  getLayerList(): LayerInfo[];
  setLayerVisible(params: SetLayerVisibleParams): Promise<{ affected: number }>;
  setLayerOpacity(params: SetLayerOpacityParams): Promise<void>;
  // ---- 特效 ----
  setWeatherEffect(params: SetWeatherEffectParams): Promise<void>;
  setHeatmap(params: SetHeatmapParams): Promise<void>;
  updateHeatmap(params: UpdateHeatmapParams): Promise<void>;
  removeHeatmap(heatmapId: string): Promise<void>;
  setParticleEffect(params: ParticleEffectParams): Promise<void>;
  setLightEffect(params: LightEffectParams): Promise<void>;
  setHighlightRegion(params: HighlightRegionParams): Promise<void>;
  // ---- 覆盖物 ----
  addPOI(params: AddPOIParams): Promise<void>;
  updatePOI(params: UpdatePOIParams): Promise<void>;
  addPath(params: AddPathParams): Promise<void>;
  add3DText(params: Add3DTextParams): Promise<void>;
  removeCovering(coveringIds: string[]): Promise<{ removed: number }>;
  clearCoverings(types?: CoveringType[]): Promise<{ removed: number }>;
  /** 实例销毁钩子：释放 WebGL 上下文与全部资源 */
  dispose(): Promise<void>;
}

export interface TwinLogger {
  debug(msg: string, meta?: object): void;
  info(msg: string, meta?: object): void;
  warn(msg: string, meta?: object): void;
  error(msg: string, meta?: object): void;
}

export interface Diagnostics {
  /** SDK 版本 */
  version: string;
  /** 渲染后端实际启用值 */
  backend: 'webgl2' | 'webgpu' | 'webgl1-fallback';
  /** 平均帧率（近 5s 滚动均值） */
  fps: number;
  /** 请求队列当前长度 */
  queueLength: number;
  /** 场景是否就绪 */
  sceneReady: boolean;
  /** 各类覆盖物计数 */
  coverings: Record<string, number>;
}

