import type { ParamSchema, ValidationError } from "../types.js";

type PlainObject = Record<string, unknown>;

const isPlainObject = (v: unknown): v is PlainObject =>
  typeof v === "object" && v !== null && !Array.isArray(v);

/** JSON Schema 子集校验器：命令注册时的元数据即运行时校验规则（设计文档 §8） */
export function validateParams(
  schema: Record<string, ParamSchema> | undefined,
  params: unknown
): ValidationError[] {
  const errors: ValidationError[] = [];

  if (schema === undefined) return errors;

  if (params === undefined || params === null) {
    const required = Object.entries(schema).filter(([, s]) => s.required);
    for (const [key] of required) {
      errors.push({ path: `/${key}`, rule: "required", detail: "缺少必填参数" });
    }
    return errors;
  }
  if (!isPlainObject(params)) {
    errors.push({ path: "/", rule: "type", detail: `期望 object，实际 ${typeof params}` });
    return errors;
  }

  const walk = (props: Record<string, ParamSchema>, obj: PlainObject, base: string): void => {
    for (const [key, rule] of Object.entries(props)) {
      const path = `${base}/${key}`;
      const value = obj[key];
      if (value === undefined) {
        if (rule.required) errors.push({ path, rule: "required", detail: "缺少必填参数" });
        continue;
      }
      validateValue(rule, value, path, errors);
    }
  };

  const validateValue = (rule: ParamSchema, value: unknown, path: string, out: ValidationError[]): void => {
    const t = rule.type;
    if (t === "number" && typeof value !== "number") {
      out.push({ path, rule: "type", detail: `期望 number，实际 ${typeof value}` });
      return;
    }
    if (t === "string" && typeof value !== "string") {
      out.push({ path, rule: "type", detail: `期望 string，实际 ${typeof value}` });
      return;
    }
    if (t === "boolean" && typeof value !== "boolean") {
      out.push({ path, rule: "type", detail: `期望 boolean，实际 ${typeof value}` });
      return;
    }
    if (t === "array") {
      if (!Array.isArray(value)) {
        out.push({ path, rule: "type", detail: `期望 array，实际 ${typeof value}` });
        return;
      }
      if (rule.items) {
        value.forEach((item, i) => validateValue(rule.items!, item, `${path}/${i}`, out));
      }
      return;
    }
    if (t === "object") {
      if (!isPlainObject(value)) {
        out.push({ path, rule: "type", detail: `期望 object，实际 ${typeof value}` });
        return;
      }
      if (rule.properties) walk(rule.properties, value, path);
      return;
    }
    if (typeof value === "number") {
      if (rule.min !== undefined && value < rule.min) {
        out.push({ path, rule: "min", detail: `${value} < ${rule.min}` });
      }
      if (rule.max !== undefined && value > rule.max) {
        out.push({ path, rule: "max", detail: `${value} > ${rule.max}` });
      }
    }
    if (typeof value === "string" && rule.enum && !rule.enum.includes(value)) {
      out.push({ path, rule: "enum", detail: `${value} 不在 [${rule.enum.join(", ")}] 内` });
    }
  };

  walk(schema, params, "");
  return errors;
}
