import type {
  CommandDefinition,
  EngineFacade,
  SceneManifest,
  LoadSceneParams,
  SwitchSceneParams,
  SetEnvironmentParams,
  CameraFlyToParams,
  CameraFocusOnParams,
  CameraRoamParams,
  SetCameraLimitParams,
  SetEntityVisibleParams,
  EntityOutlineParams,
  EntityHighlightParams,
  LocateEntityParams,
  EntitySelector,
  MoveEntityByPathParams,
  SetLayerVisibleParams,
  SetLayerOpacityParams,
  SetWeatherEffectParams,
  SetHeatmapParams,
  UpdateHeatmapParams,
  ParticleEffectParams,
  LightEffectParams,
  HighlightRegionParams,
  AddPOIParams,
  UpdatePOIParams,
  AddPathParams,
  Add3DTextParams,
  RemoveCoveringParams,
  ClearCoveringsParams,
  SceneInfo,
  CameraState,
  LayerInfo,
  EntityInfo,
} from "../types.js";
import { ErrorCode } from "../types.js";
import { TwinError } from "./errors.js";

/**
 * 内置命令全集（33 个，v1.0 目录）：全部经 EngineFacade 门面操作引擎，
 * handler 内不触碰 Babylon 类型。真实引擎由 M2 的 digital-twin-core 提供。
 */
export function createBuiltinCommands(
  engine: EngineFacade,
  scenes: Record<string, SceneManifest>
): CommandDefinition[] {
  const manifestFor = (sceneId: string): SceneManifest => {
    const manifest = scenes[sceneId];
    if (!manifest) {
      throw new TwinError(ErrorCode.SCENE_NOT_FOUND, `场景 ${sceneId} 未在 scenes 清单中注册`);
    }
    return manifest;
  };

  const def = <P, R>(
    name: string,
    category: CommandDefinition["category"],
    handler: (params: P) => Promise<R> | R,
    extra: Partial<CommandDefinition> = {}
  ): CommandDefinition => ({
    name,
    category,
    handler: (_ctx, params: P) => handler(params),
    protected: true,
    since: "1.0.0",
    ...extra,
  });

  /**
   * 实体选择器统一校验：必须且只能包含 eids / entityNames / customIds 之一且非空数组。
   * 空选择器几乎必然是调用方 bug，及早以 2002 暴露。
   */
  const requireSelector = (selector: EntitySelector, command: string): EntitySelector => {
    const asRecord = selector as Record<string, unknown>;
    const valid = (["eids", "entityNames", "customIds"] as const).filter(
      (key) => Array.isArray(asRecord[key]) && (asRecord[key] as unknown[]).length > 0
    );
    if (valid.length !== 1) {
      throw new TwinError(
        ErrorCode.INVALID_PARAMS,
        `${command}: targets 选择器必须且只能包含 eids / entityNames / customIds 之一（非空数组）`
      );
    }
    return selector;
  };

  return [
    // ---- 场景（4）----
    def<LoadSceneParams, SceneInfo>(
      "LoadScene",
      "scene",
      (p) => engine.loadScene(manifestFor(p.sceneId), p),
      { queue: "serial" }
    ),
    def<SwitchSceneParams, SceneInfo>(
      "SwitchScene",
      "scene",
      (p) => engine.switchScene(manifestFor(p.sceneId), p),
      { queue: "serial" }
    ),
    def<void, SceneInfo>("GetSceneInfo", "scene", () => engine.getSceneInfo()),
    def<SetEnvironmentParams, void>("SetEnvironment", "scene", (p) => engine.setEnvironment(p)),
    // ---- 相机（7）----
    def<CameraFlyToParams, CameraState>("CameraFlyTo", "camera", (p) => engine.cameraFlyTo(p), {
      queue: "latest",
    }),
    def<CameraFocusOnParams, CameraState>("CameraFocusOn", "camera", (p) => engine.cameraFocusOn(p)),
    def<CameraRoamParams, { roamId: string }>("CameraRoamStart", "camera", (p) =>
      engine.cameraRoamStart(p)
    ),
    def<void, void>("CameraRoamStop", "camera", () => engine.cameraRoamStop()),
    def<void, CameraState>("GetCameraInfo", "camera", () => engine.getCameraState()),
    def<SetCameraLimitParams, void>("SetCameraLimit", "camera", (p) => engine.setCameraLimit(p)),
    def<void, CameraState>("ResetCameraView", "camera", () => engine.resetCameraView()),
    // ---- 实体（6）----
    def<SetEntityVisibleParams, { affected: number }>("SetEntityVisible", "entity", (p) =>
      engine.setEntityVisible({ ...p, targets: requireSelector(p.targets, "SetEntityVisible") })
    ),
    def<EntityOutlineParams, { affected: number }>("SetEntityOutline", "entity", (p) =>
      engine.setEntityOutline({ ...p, targets: requireSelector(p.targets, "SetEntityOutline") })
    ),
    def<EntityHighlightParams, { affected: number }>("SetEntityHighlight", "entity", (p) =>
      engine.setEntityHighlight({ ...p, targets: requireSelector(p.targets, "SetEntityHighlight") })
    ),
    def<LocateEntityParams, void>("LocateEntity", "entity", (p) =>
      engine.locateEntity({ ...p, targets: requireSelector(p.targets, "LocateEntity") })
    ),
    def<EntitySelector, EntityInfo[]>("GetEntityInfo", "entity", (p) =>
      engine.getEntityInfo(requireSelector(p, "GetEntityInfo"))
    ),
    def<MoveEntityByPathParams, { moveId: string }>("MoveEntityByPath", "entity", (p) =>
      engine.moveEntityByPath({ ...p, targets: requireSelector(p.targets, "MoveEntityByPath") })
    ),
    // ---- 图层（3）----
    def<void, LayerInfo[]>("GetLayerList", "layer", () => engine.getLayerList()),
    def<SetLayerVisibleParams, { affected: number }>("SetLayerVisible", "layer", (p) =>
      engine.setLayerVisible(p)
    ),
    def<SetLayerOpacityParams, void>("SetLayerOpacity", "layer", (p) => engine.setLayerOpacity(p)),
    // ---- 特效（7）----
    def<SetWeatherEffectParams, void>("SetWeatherEffect", "effect", (p) => engine.setWeatherEffect(p)),
    def<SetHeatmapParams, void>("SetHeatmap", "effect", (p) => engine.setHeatmap(p)),
    def<UpdateHeatmapParams, void>("UpdateHeatmap", "effect", (p) => engine.updateHeatmap(p)),
    def<{ heatmapId: string }, void>("RemoveHeatmap", "effect", (p) => engine.removeHeatmap(p.heatmapId)),
    def<ParticleEffectParams, void>("SetParticleEffect", "effect", (p) => engine.setParticleEffect(p)),
    def<LightEffectParams, void>("SetLightEffect", "effect", (p) => engine.setLightEffect(p)),
    def<HighlightRegionParams, void>("SetHighlightRegion", "effect", (p) => engine.setHighlightRegion(p)),
    // ---- 标注 / 覆盖物（6）----
    def<AddPOIParams, void>("AddPOI", "covering", (p) => engine.addPOI(p)),
    def<UpdatePOIParams, void>("UpdatePOI", "covering", (p) => engine.updatePOI(p)),
    def<AddPathParams, void>("AddPath", "covering", (p) => engine.addPath(p)),
    def<Add3DTextParams, void>("Add3DText", "covering", (p) => engine.add3DText(p)),
    def<RemoveCoveringParams, { removed: number }>("RemoveCovering", "covering", (p) =>
      engine.removeCovering(p.coveringIds)
    ),
    def<ClearCoveringsParams, { removed: number }>("ClearCoverings", "covering", (p) =>
      engine.clearCoverings(p.types)
    ),
  ];
}
