import type { ApiResponse, CommandContext, CommandDefinition, TwinLogger } from "../types.js";
import { ErrorCode } from "../types.js";
import { TwinError, toTwinError, errCommandNotFound } from "./errors.js";
import { fail, ok } from "./envelope.js";
import { validateParams } from "./validate.js";
import { CommandQueue } from "./queue.js";

export interface SchedulerDeps {
  logger: TwinLogger;
  defaultTimeout: number;
  /** 引擎就绪检查：场景类/相机类命令执行前置校验 */
  isReady: () => boolean;
  /** 是否需要引擎就绪才可执行（查询类命令可放宽，由命令定义方决定） */
  requiresEngine: (def: CommandDefinition) => boolean;
  /** 命令执行环境（engine 门面等），在 run 时注入 ctx */
  context: Omit<CommandContext, "signal" | "requestId">;
}

/**
 * L2 命令调度器：注册表路由 → 参数校验 → 就绪检查 → 排队策略 → 超时控制 → 统一信封。
 * 命令级失败永不 reject（统一 code != 0 resolve），仅 SDK 编程错误抛出（设计文档 §4.2）。
 */
export class Scheduler {
  private destroyed = false;

  constructor(
    private readonly registry: { get(name: string): CommandDefinition | undefined },
    private readonly queue: CommandQueue,
    private readonly deps: SchedulerDeps
  ) {}

  markDestroyed(): void {
    this.destroyed = true;
    this.queue.abortAll();
  }

  async execute<P, R>(command: string, params?: P): Promise<ApiResponse<R>> {
    const startedAt = Date.now();
    const def = this.registry.get(command);
    if (!def) {
      return fail({ command, startedAt }, errCommandNotFound(command));
    }
    if (this.destroyed) {
      return fail(
        { command, startedAt },
        new TwinError(ErrorCode.ENGINE_DESTROYED, "实例已销毁")
      );
    }
    if (this.deps.requiresEngine(def) && !this.deps.isReady()) {
      return fail(
        { command, startedAt },
        new TwinError(ErrorCode.ENGINE_NOT_READY, `命令 ${command} 需要场景就绪后执行（先完成 LoadScene）`)
      );
    }

    const validationErrors = validateParams(def.params as Record<string, never> | undefined, params);
    if (validationErrors.length > 0) {
      return fail({ command, startedAt }, toTwinError(invalid(command, validationErrors)));
    }

    if (def.deprecated) {
      this.deps.logger.warn(
        `命令 ${command} 自 ${def.deprecated.since} 起弃用${def.deprecated.useInstead ? `，请改用 ${def.deprecated.useInstead}` : ""}`
      );
    }

    const timeout = def.timeout ?? this.deps.defaultTimeout;
    // 运行控制器：超时触发 abort；latest 排队策略的取代信号也会级联到 handler 的 ctx.signal
    const runController = new AbortController();
    const timer = timeout > 0 ? setTimeout(() => runController.abort(), timeout) : null;

    try {
      const requestId = `req-${command}-${startedAt}-${Math.random().toString(36).slice(2, 8)}`;
      const ctx: CommandContext = {
        ...this.deps.context,
        signal: runController.signal,
        requestId,
      };
      const raw = await this.queue.run(def, async (queueSignal) => {
        if (queueSignal.aborted) runController.abort();
        else queueSignal.addEventListener("abort", () => runController.abort());
        // 超时/取消以 Promise.race 实现：handler 可不感知 signal，但命令语义上仍按时限返回
        return await Promise.race([
          def.handler(ctx, params as never),
          new Promise<never>((_, reject) => {
            if (runController.signal.aborted) reject(abortError(command));
            else runController.signal.addEventListener("abort", () => reject(abortError(command)));
          }),
        ]);
      });
      return ok({ command, startedAt, requestId }, raw as R);
    } catch (err) {
      const twinErr = toTwinError(err);
      if (twinErr.code === ErrorCode.COMMAND_TIMEOUT) {
        return fail(
          { command, startedAt },
          new TwinError(ErrorCode.COMMAND_TIMEOUT, `命令 ${command} 执行超时（${timeout}ms）`)
        );
      }
      this.deps.logger.error(`命令 ${command} 失败: ${twinErr.message}`);
      return fail({ command, startedAt }, twinErr);
    } finally {
      if (timer) clearTimeout(timer);
    }
  }
}

function abortError(command: string): TwinError {
  return new TwinError(ErrorCode.COMMAND_TIMEOUT, `命令 ${command} 被取消`);
}

function invalid(
  command: string,
  errors: ReadonlyArray<{ path: string; rule: string; detail: string }>
): TwinError {
  const first = errors[0]!;
  return new TwinError(
    ErrorCode.INVALID_PARAMS,
    `${command} 参数校验失败 — ${first.path} ${first.rule}: ${first.detail}`,
    errors
  );
}
